import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { ModalController, NavController } from '@ionic/angular';
import { TranslateService } from '@ngx-translate/core';
import { MagModalConfirmComponent } from '@rsApp/components/mag-confirm-modal/mag-modal-confirm';

@Component({
  selector: 'checkout-v2',
  templateUrl: './checkout.html',
  styleUrls: ['./checkout.scss'],
})
export class CheckoutPageComponent {
  private entryRoute: string | null = null;
  private enteredFromSignIn = false;
  private readonly checkoutReturnFlagKey = 'fromCheckoutAfterSignIn';
  public hasGiftCertificateValue = false;
  public dxpMagCheckoutInformation = '';

  constructor(
    public router: Router,
    public route: ActivatedRoute,
    private navCtrl: NavController,
    private modalCtrl: ModalController,
    private translate: TranslateService
  ) {
    const currentNavigation = this.router.getCurrentNavigation();
    const navigationState = currentNavigation?.extras.state || history.state;
    const previousNavigation = currentNavigation?.previousNavigation;
    const previousNavigationUrl =
      previousNavigation?.finalUrl?.toString?.() || previousNavigation?.extractedUrl?.toString?.() || null;

    this.entryRoute = (navigationState?.fromRoute as string) || previousNavigationUrl;
    this.enteredFromSignIn =
      (navigationState?.fromSignIn as boolean) || this.entryRoute?.startsWith('/sign-in') || false;

    if (this.enteredFromSignIn) {
      this.markCheckoutReturnFromSignIn();
    }

    this.preventBackNavigation();
  }

  ionViewWillEnter() {
    const params = this.route.snapshot.paramMap;
    const serviceUrlSlug = params.get('serviceUrlSlug');
    if (!serviceUrlSlug) {
      console.warn('Service url slug not found');
      return;
    }
    customElements.whenDefined('mag-checkout-information').then(() => {
      this.dxpMagCheckoutInformation = `<mag-checkout-information service-slug="${serviceUrlSlug}"></mag-checkout-information>`;
    });
  }

  ionViewDidEnter() {
    // Add event listener to handle message from DXP Component
    window.addEventListener('message', this.handleEvent);
  }

  ionViewDidLeave() {
    if (!this.hasGiftCertificateValue) {
      this.dxpMagCheckoutInformation = '';
    }

    // Clean up event listener
    window.removeEventListener('message', this.handleEvent);
  }

  private handleEvent = (event) => {
    const { action, data } = event?.data || {};
    if (action === 'MagHasGiftCertificateValue') {
      this.hasGiftCertificateValue = data?.hasGiftCertificateValue ?? false;
    }
  };

  preventBackNavigation() {
    this.navCtrl.navigateBack = () => {
      if (this.hasGiftCertificateValue) {
        this.openConfirmModal();
      } else {
        if (this.enteredFromSignIn) {
          this.markCheckoutReturnFromSignIn();
          this.navCtrl.navigateRoot(['/tabs/home']);
          return;
        }

        this.navCtrl.back();
      }
      return Promise.resolve(false);
    };
  }

  handleBackNavigation() {
    if (this.enteredFromSignIn) {
      this.markCheckoutReturnFromSignIn();
      this.navCtrl.navigateRoot(['/tabs/home']);
      return;
    }

    this.navCtrl.back();
  }

  private markCheckoutReturnFromSignIn(): void {
    if (typeof window === 'undefined') return;
    try {
      window.sessionStorage.setItem(this.checkoutReturnFlagKey, 'true');
    } catch (error) {
      console.warn('Unable to persist checkout return flag', error);
    }
  }

  async openConfirmModal() {
    const modal = await this.modalCtrl.create({
      component: MagModalConfirmComponent,
      componentProps: {
        title: this.translate.instant('checkout.leavePageTitle'),
        description: this.translate.instant('checkout.leavePageDescription'),
        confirmTitle: this.translate.instant('checkout.stay'),
        cancelTitle: this.translate.instant('checkout.leavePage'),
        verticalButtons: false,
      },
      cssClass: 'mag-confirm-modal',
    });

    modal.onDidDismiss().then((result) => {
      if (result?.data === false) {
        this.hasGiftCertificateValue = false;
        const payload = {
          action: 'MagGiftCertificateConfirmLeavePage',
          data: {
            leave: true,
          },
        };
        window.postMessage(payload, window.location.origin);
        this.handleBackNavigation();
      }
    });

    await modal.present();
  }
}
